const fs = require('fs');
const path = require('path');

// Read the .env.test file to determine which keys need rotation support
const envFilePath = '.env.test';
const tempEnvFilePath = '.env.test.tmp';
const logFilePath = 'rotation-log.json';

// Keys to support rotation (read from .env.test)
const keysToRotate = [];

try {
  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const lines = envContent.split('\n');

  lines.forEach(line => {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (trimmedLine && !trimmedLine.startsWith('#')) {
      const [key] = trimmedLine.split('=', 1);
      if (key === 'ANTHROPIC_API_KEY' || key === 'STRIPE_SECRET_KEY') {
        keysToRotate.push(key);
      }
    }
  });
} catch (error) {
  console.error('Error reading .env.test file:', error.message);
  process.exit(1);
}

/**
 * Rotates a key by generating a new placeholder and updating the .env.test file atomically.
 * @param {string} keyName - The name of the key to rotate (e.g., 'ANTHROPIC_API_KEY')
 */
function rotateKey(keyName) {
  // Validate that the key is supported for rotation
  if (!keysToRotate.includes(keyName)) {
    throw new Error(`Key rotation not supported for: ${keyName}`);
  }

  try {
    // Read current .env file
    const currentEnvContent = fs.readFileSync(envFilePath, 'utf8');
    const lines = currentEnvContent.split('\n');

    // Generate new placeholder value
    const newValue = generatePlaceholder(keyName);

    // Update the key value in the content
    const updatedLines = lines.map(line => {
      const trimmedLine = line.trim();
      if (trimmedLine && !trimmedLine.startsWith('#')) {
        const [key] = trimmedLine.split('=', 1);
        if (key === keyName) {
          return `${keyName}=${newValue}`;
        }
      }
      return line; // Return unchanged if not the target key or is a comment/empty
    });

    const updatedEnvContent = updatedLines.join('\n');

    // Write to temporary file first
    fs.writeFileSync(tempEnvFilePath, updatedEnvContent, 'utf8');

    // Atomic rename to replace the original file
    fs.renameSync(tempEnvFilePath, envFilePath);

    // Log the rotation event
    logRotationEvent(keyName);

    console.log(`Successfully rotated key: ${keyName}`);
  } catch (error) {
    // Clean up temp file if it exists
    try {
      if (fs.existsSync(tempEnvFilePath)) {
        fs.unlinkSync(tempEnvFilePath);
      }
    } catch (cleanupError) {
      console.warn('Failed to clean up temp file:', cleanupError.message);
    }

    throw error;
  }
}

/**
 * Generates a placeholder value for a given key name.
 * @param {string} keyName - The name of the key
 * @returns {string} - The generated placeholder value
 */
function generatePlaceholder(keyName) {
  const suffix = Math.random().toString(36).substring(2, 15);

  if (keyName === 'ANTHROPIC_API_KEY') {
    return `REDACTED_ANTHROPIC_KEY${suffix}`;
  } else if (keyName === 'STRIPE_SECRET_KEY') {
    return `REDACTED_STRIPE_LIVE${suffix}`;
  }

  // Default fallback
  return `new-placeholder-${suffix}`;
}

/**
 * Logs the rotation event with timestamp and key name.
 * @param {string} keyName - The name of the rotated key
 */
function logRotationEvent(keyName) {
  try {
    const logEntry = {
      timestamp: new Date().toISOString(),
      keyName: keyName
    };

    let logData = [];

    // Read existing log data if file exists and has content
    if (fs.existsSync(logFilePath)) {
      const logFileContent = fs.readFileSync(logFilePath, 'utf8').trim();
      if (logFileContent) {
        logData = JSON.parse(logFileContent);
      }
    }

    // Append new entry
    logData.push(logEntry);

    // Write back to log file
    fs.writeFileSync(logFilePath, JSON.stringify(logData, null, 2) + '\n', 'utf8');
  } catch (error) {
    console.error('Failed to log rotation event:', error.message);
    // Don't throw as this shouldn't block the key rotation
  }
}

module.exports = { rotateKey };

// key-rotation.js
const fs = require('fs').promises;
const path = require('path');

// Configuration
const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';
const CANARY_PREFIX = 'CANARY';

// Read and parse the environment file to extract key names that need rotation
async function getKeyNamesForRotation() {
  try {
    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const keyNames = [];

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key] = trimmed.split('=', 1);
        if (key && key.includes(CANARY_PREFIX)) {
          keyNames.push(key);
        }
      }
    }

    return keyNames;
  } catch (error) {
    throw new Error(`Failed to read or parse ${ENV_FILE}: ${error.message}`);
  }
}

// Generate a new key placeholder with a random 12-character hex suffix
function generateNewKeyPlaceholder() {
  const suffix = Array.from({ length: 12 }, () => 
    Math.floor(Math.random() * 16).toString(16)
  ).join('');
  return `${CANARY_PREFIX}-api-key-${suffix}`;
}

// Rotate a specific key by name
async function rotateKey(keyName) {
  try {
    // Validate keyName
    if (!keyName || typeof keyName !== 'string') {
      throw new Error('Invalid key name: must be a non-empty string');
    }

    // Get current keys to ensure the key exists
    const keys = await getKeyNamesForRotation();
    if (!keys.includes(keyName)) {
      throw new Error(`Key '${keyName}' not found or not eligible for rotation`);
    }

    // Read current file content
    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split('\n');

    // Generate new key value
    const newKeyValue = generateNewKeyPlaceholder();

    // Replace the key value in the file content
    const updatedLines = lines.map(line => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, value] = trimmed.split('=', 2);
        if (key === keyName) {
          // Replace only the value part, preserving original formatting
          return line.replace(=.*$/, `=${newKeyValue}`);
        }
      }
      return line;
    });

    const updatedContent = updatedLines.join('\n');

    // Write to temporary file first
    const tempFilePath = `${ENV_FILE}.tmp`;
    await fs.writeFile(tempFilePath, updatedContent, 'utf8');

    // Atomically replace the original file
    await fs.rename(tempFilePath, ENV_FILE);

    // Log the rotation event
    const logEntry = {
      timestamp: new Date().toISOString(),
      keyName: keyName,
      action: 'key_rotation'
    };

    let logData = [];
    try {
      const logContent = await fs.readFile(LOG_FILE, 'utf8');
      logData = JSON.parse(logContent);
    } catch (error) {
      // Log file doesn't exist or is invalid, start fresh
    }

    logData.push(logEntry);
    await fs.writeFile(LOG_FILE, JSON.stringify(logData, null, 2), 'utf8');

    console.log(`Successfully rotated key: ${keyName}`);
    return true;
  } catch (error) {
    console.error(`Key rotation failed for ${keyName}: ${error.message}`);
    throw error;
  }
}

module.exports = { rotateKey, getKeyNamesForRotation };

