// key-rotation.js
const fs = require('fs');
const path = require('path');

const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Read and parse the .env file to extract key names
function getKeyNamesFromFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const keyNames = [];
  content.split('\n').forEach(line => {
    const match = line.trim().match(/^([^=]+)=/);
    if (match) {
      keyNames.push(match[1]);
    }
  });
  return keyNames;
}

// Check if the key name is one that should be rotated
function isRotatableKey(keyName) {
  const rotatableKeys = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];
  return rotatableKeys.includes(keyName);
}

// Generate a new placeholder key value
function generateNewKey() {
  const random = Math.random().toString(36).substr(2, 10);
  return `NEW_PLACEHOLDER_${random}`;
}

// Rotate a key by updating the .env file
function rotateKey(keyName) {
  if (!isRotatableKey(keyName)) {
    throw new Error(`Key rotation not supported for: ${keyName}`);
  }

  const tempFile = `${ENV_FILE}.tmp`;
  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');
  const newKey = generateNewKey();

  const updatedLines = lines.map(line => {
