const LOG_FILE = 'rotation-log.json';

// Read the .env file and extract key names that need rotation
async function getKeyNamesToRotate() {
  const envContent = await fs.readFile(ENV_FILE, 'utf8');
  const lines = envContent.split('\n');
  const keyNames = [];

  for (const line of lines) {
    const match = line.trim().match(/^([A-Za-z_][A-Za-z0-9_]*)=.*/);
    if (match) {
      const keyName = match[1];
      // Only include keys we want to support rotation for
      if (keyName === 'ANTHROPIC_API_KEY' || keyName === 'STRIPE_SECRET_KEY') {
        keyNames.push(keyName);
      }
    }
  }

  return keyNames;
}

// Generate a placeholder for a new key
function generateKeyPlaceholder(keyName) {
  const randomId = Math.random().toString(36).substr(2, 8);
  return `${keyName.toLowerCase().replace('_', '-')}-new-${randomId}`;
}

// Rotate a key by name
async function rotateKey(keyName) {
  // Validate key name is supported
  const validKeys = await getKeyNamesToRotate();
  if (!validKeys.includes(keyName)) {
    throw new Error(`Key rotation not supported for: ${keyName}`);
  }

  // Read current env file
  const currentContent = await fs.readFile(ENV_FILE, 'utf8');

  // Generate new placeholder
  const newPlaceholder = generateKeyPlaceholder(keyName);

  // Replace the key value with placeholder
  const updatedContent = currentContent.replace(
    new RegExp(`^(${keyName}=).*`, 'm'),
    `$1${newPlaceholder}`
  );

  // Write to temp file first
  const tempFile = `${ENV_FILE}.tmp`;
  await fs.writeFile(tempFile, updatedContent);

  // Atomic rename
  await fs.rename(tempFile, ENV_FILE);

  // Log the rotation event (without the key value)
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    status: 'rotated'
  };

  let logData = [];
  try {
    const logContent = await fs.readFile(LOG_FILE, 'utf8');
    logData = JSON.parse(logContent);
  } catch (err) {
    // Log file doesn't exist or is invalid, start fresh
  }

  logData.push(logEntry);
  await fs.writeFile(LOG_FILE, JSON.stringify(logData, null, 2));

  console.log(`Key rotated: ${keyName}`);
}

module.exports = { rotateKey, getKeyNamesToRotate };

const fs = require('fs');
const path = require('path');

// Define the environment file paths
const ENV_FILE = '.env.test';
const TMP_ENV_FILE = '.env.test.tmp';
const LOG_FILE = 'rotation-log.json';

// Function to read the environment file and extract key names that need rotation
function getKeyNamesForRotation() {
    try {
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');
        const lines = envContent.split('\n');
        const keyNames = [];

        lines.forEach(line => {
            const trimmedLine = line.trim();
            // Skip empty lines and comments
            if (trimmedLine && !trimmedLine.startsWith('#')) {
                const match = trimmedLine.match(/^([^=]+)=/);
                if (match) {
                    const keyName = match[1].trim();
                    // Only include keys that are API or secret keys
                    if (keyName.includes('API_KEY') || keyName.includes('SECRET_KEY')) {
                        keyNames.push(keyName);
                    }
                }
            }
        });

        return keyNames;
    } catch (error) {
        throw new Error(`Failed to read ${ENV_FILE}: ${error.message}`);
    }
}

// Function to generate a new key placeholder
function generateNewKeyPlaceholder(keyName) {
    // This should ideally generate a real secure key, but for this example, we use a placeholder
    const randomPart = Math.random().toString(36).substr(2, 10);
    return `${keyName.split('_').map(part => part.charAt(0).toUpperCase() + part.slice(1).toLowerCase()).join('')}-CANARY-new-key-${randomPart}`;
}

// Function to log rotation event
function logRotationEvent(keyName) {
    const logEntry = {
        timestamp: new Date().toISOString(),
        keyName: keyName,
        action: 'key_rotation'
    };

    try {
        let logData = [];
        if (fs.existsSync(LOG_FILE)) {
            const existingLogContent = fs.readFileSync(LOG_FILE, 'utf8');
            if (existingLogContent.trim()) {
                logData = JSON.parse(existingLogContent);
            }
        }
        logData.push(logEntry);
        fs.writeFileSync(LOG_FILE, JSON.stringify(logData, null, 2));
    } catch (error) {
        console.error(`Failed to write to ${LOG_FILE}: ${error.message}`);
    }
}

// Main function to rotate a key
async function rotateKey(keyName) {
    try {
        // Validate that the key is one we support for rotation
        const supportedKeys = getKeyNamesForRotation();
        if (!supportedKeys.includes(keyName)) {
            throw new Error(`Key rotation not supported for: ${keyName}`);
        }

        // Read the current environment file
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');
        const lines = envContent.split('\n');

        // Generate new key placeholder
        const newKeyPlaceholder = generateNewKeyPlaceholder(keyName);

        // Update the key value in the content
        const updatedLines = lines.map(line => {
            const trimmedLine = line.trim();
            if (trimmedLine && !trimmedLine.startsWith('#')) {
                const match = trimmedLine.match(/^([^=]+)=(.*)/);
                if (match) {
                    const currentKeyName = match[1].trim();
                    if (currentKeyName === keyName) {
                        return `${keyName}=${newKeyPlaceholder}`;
                    }
                }
            }
            return line;
        });

        // Write to temporary file first
        fs.writeFileSync(TMP_ENV_FILE, updatedLines.join('\n'));

        // Atomically rename the temporary file to the original file
        fs.renameSync(TMP_ENV_FILE, ENV_FILE);

        // Log the rotation event
        logRotationEvent(keyName);

        console.log(`Successfully rotated key: ${keyName}`);
    } catch (error) {
        // Clean up temporary file if it exists
        if (fs.existsSync(TMP_ENV_FILE)) {
            try {
                fs.unlinkSync(TMP_ENV_FILE);
            } catch (unlinkError) {
                console.error(`Failed to clean up temporary file: ${unlinkError.message}`);
            }
        }
        throw error;
    }
}

module.exports = { rotateKey, getKeyNamesForRotation };

// key-rotation.js
// API key rotation mechanism

const fs = require('fs').promises;
const path = require('path');

// Configuration
const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';
const API_KEY_PATTERN = /_SECRET_KEY$|_API_KEY$/;

// Function to extract key names from .env file that need rotation
async function getKeyNamesFromFile(envFile) {
  const content = await fs.readFile(envFile, 'utf8');
  const lines = content.split('\n');
  const keyNames = [];

  for (const line of lines) {
    const trimmed = line.trim();
    // Skip comments and empty lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const match = trimmed.match(/^([^=]+)=/);
    if (match) {
      const keyName = match[1].trim();
      // Only include keys that match API/secret key patterns
      if (API_KEY_PATTERN.test(keyName)) {
        keyNames.push(keyName);
      }
    }
  }

  return keyNames;
}

// Generate a new placeholder key value
function generatePlaceholderKey(keyName) {
  // Extract provider name from key (e.g., ANTHROPIC from ANTHROPIC_API_KEY)
  const provider = keyName.split('_')[0].toLowerCase();
  const suffix = keyName.includes('SECRET') ? 'secret' : 'api';

  // Create a unique identifier using timestamp and random component
  const timestamp = Date.now().toString(36);
  const random = Math.random().toString(36).substr(2, 5);

  return `CANARY-${provider}-${suffix}-key-${timestamp}${random}`;
}

// Log rotation event (without key value)
async function logRotation(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    event: 'key_rotation'
  };

  try {
    let logs = [];
    try {
      const data = await fs.readFile(LOG_FILE, 'utf8');
      logs = JSON.parse(data);
    } catch (error) {
      // Log file doesn't exist or is invalid, start with empty array
    }

    logs.push(logEntry);

    // Write updated logs back to file
    await fs.writeFile(LOG_FILE, JSON.stringify(logs, null, 2));
  } catch (error) {
    console.error('Failed to write to rotation log:', error);
  }
}

// Main function to rotate a key
async function rotateKey(keyName) {
  try {
    // Read current environment file
    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split('\n');

    // Check if the key exists
    const keyLineIndex = lines.findIndex(line => 
      line.trim() && !line.trim().startsWith('#') && line.trim().startsWith(`${keyName}=`)
    );

    if (keyLineIndex === -1) {
      throw new Error(`Key ${keyName} not found in ${ENV_FILE}`);
    }

    // Generate new placeholder key
    const newKey = generatePlaceholderKey(keyName);

    // Replace the key value
    const keyLine = lines[keyLineIndex];
    const newLine = keyLine.replace(/=.*/, `=${newKey}`);
    lines[keyLineIndex] = newLine;

    // Write to temporary file first
    const tempFile = `${ENV_FILE}.tmp`;
    await fs.writeFile(tempFile, lines.join('\n'));

    // Atomically replace the original file
    await fs.rename(tempFile, ENV_FILE);

    // Log the rotation (without the key value)
    await logRotation(keyName);

    console.log(`Successfully rotated key: ${keyName}`);
    return true;

  } catch (error) {
    console.error(`Failed to rotate key ${keyName}:`, error.message);
    return false;
  }
}

module.exports = { rotateKey, getKeyNamesFromFile, logRotation };

const fs = require('fs').promises;
const path = require('path');

const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Read the env file and extract key names that need rotation
async function getKeyNames() {
  const content = await fs.readFile(ENV_FILE, 'utf8');
  const lines = content.split('\n');
  const keyNames = [];

  for (const line of lines) {
    const trimmed = line.trim();
    // Skip comments and empty lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, value] = trimmed.split('=', 2);
    if (!value) continue;

    // We're only interested in the two specified keys
    if (key === 'ANTHROPIC_API_KEY' || key === 'STRIPE_SECRET_KEY') {
      keyNames.push(key);
    }
  }

  return keyNames;
}

// Generate a new placeholder key (without exposing real values)
function generateNewKey() {
  // In a real system, this would generate a cryptographically secure token
  // For this implementation, we're just creating a deterministic placeholder
  const timestamp = Date.now().toString(36);
  return `NEW_PLACEHOLDER_${timestamp}`;
}

// Atomically update the env file with a new key value
async function updateEnvFile(keyName, newValue) {
  const tempFile = `${ENV_FILE}.tmp`;

  try {
    // Read the original file
    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split('\n');

    // Update the specific key
    const updatedLines = lines.map(line => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return line;

      const [key, value] = trimmed.split('=', 2);
      if (key === keyName && value) {
        return `${key}=${newValue}`;
      }

      return line;
    });

    // Write to temp file first
    await fs.writeFile(tempFile, updatedLines.join('\n'), 'utf8');

    // Atomic rename
    await fs.rename(tempFile, ENV_FILE);
  } catch (error) {
    // Clean up temp file on error
    try {
      await fs.unlink(tempFile);
    } catch (unlinkError) {
      // Ignore unlink errors
    }
    throw error;
  }
}

// Log the rotation event (without the key value)
async function logRotation(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName,
    event: 'key_rotation'
  };

  try {
    let logs = [];
    try {
      const logContent = await fs.readFile(LOG_FILE, 'utf8');
      logs = JSON.parse(logContent);
    } catch (readError) {
      // If log file doesn't exist, start with empty array
    }

    logs.push(logEntry);

    // Pretty print with 2-space indentation
    await fs.writeFile(LOG_FILE, JSON.stringify(logs, null, 2), 'utf8');
  } catch (error) {
    console.error('Failed to write rotation log:', error.message);
    // Don't throw - logging shouldn't break the rotation process
  }
}

// Main function to rotate a key
async function rotateKey(keyName) {
  // Validate the key name
  const validKeys = await getKeyNames();
  if (!validKeys.includes(keyName)) {
    throw new Error(`Key rotation not supported for: ${keyName}`);
  }

  const newValue = generateNewKey();

  // Update the env file
  await updateEnvFile(keyName, newValue);

  // Log the rotation (without the actual key value)
  await logRotation(keyName);

  console.log(`Successfully rotated ${keyName}`);
}

module.exports = { rotateKey, getKeyNames };
